// Stub Stripe SDK behaving like the API DOES from 2026-08-26.preview onward:
// passing `payment_method_types` to paymentIntents.create/update/confirm or
// setupIntents.create/update now throws, mirroring the real 400
// `payment_method_types_no_longer_supported` error described at
// https://docs.stripe.com/changelog/dahlia/2026-08-26/removes-payment-method-types-parameter-from-payment-intents-setup-intents.md

class StripeApiError extends Error {
  constructor(code) {
    super(`Stripe API error: ${code}`);
    this.code = code;
    this.statusCode = 400;
  }
}

function rejectPaymentMethodTypes(params) {
  if (params && Object.prototype.hasOwnProperty.call(params, 'payment_method_types')) {
    throw new StripeApiError('payment_method_types_no_longer_supported');
  }
}

export default class Stripe {
  constructor(apiKey, opts) {
    this.apiKey = apiKey;
    this.opts = opts || {};
    let counter = 0;

    this.paymentIntents = {
      create: async (params) => {
        rejectPaymentMethodTypes(params);
        if (typeof params.amount !== 'number') throw new Error('amount is required');
        if (!params.currency) throw new Error('currency is required');
        counter += 1;
        return { id: `pi_${counter}`, amount: params.amount, currency: params.currency, status: 'requires_payment_method' };
      },
      update: async (id, params) => {
        rejectPaymentMethodTypes(params);
        return { id, ...params };
      },
      confirm: async (id, params) => {
        rejectPaymentMethodTypes(params);
        return { id, status: 'succeeded' };
      },
    };

    this.setupIntents = {
      create: async (params) => {
        rejectPaymentMethodTypes(params);
        counter += 1;
        return { id: `seti_${counter}`, status: 'requires_payment_method' };
      },
      update: async (id, params) => {
        rejectPaymentMethodTypes(params);
        return { id, ...params };
      },
    };
  }
}
